seq = "".join(l.strip() for l in open("region.fasta").read().splitlines()[1:])
n=len(seq)
comp=str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]

def find_orfs(s, minaa=60):
    res=[]
    for frame in range(3):
        start=None; pos=frame
        while pos+3<=n:
            cod=s[pos:pos+3]
            if cod=="ATG" and start is None: start=pos
            if cod in ("TAA","TAG","TGA"):
                if start is not None:
                    if (pos-start)//3>=minaa: res.append((start,pos+3))
                    start=None
            pos+=3
        if start is not None and (len(s)-start)//3>=minaa:
            res.append((start,len(s)))
    return res

print("ORFs >=60 aa (forward coordinates, strand):")
rows=[]
for a,b in find_orfs(seq):
    rows.append((a,b,'+'))
r=rc(seq)
for a,b in find_orfs(r):
    fa,fb=n-b,n-a
    rows.append((fa,fb,'-'))
for fa,fb,st in sorted(rows):
    print(f"  {fa+1:5d}-{fb:5d} ({fb-fa:4d} nt, {(fb-fa)//3:3d} aa)  strand {st}")

print("\nFine GC (100-bp windows, only window start shown for 1100-2100):")
for i in range(1100,2100,100):
    w=seq[i:i+100]; print(f"  {i+1:5d}-{i+100:5d}  GC={(w.count('G')+w.count('C'))/100:.2f}")

